    def sget(obj, key, default=None):
        try:
            if isinstance(obj, dict):
                return obj.get(key, default)
        except Exception:
            pass
        return default

    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def md(a, b, c, d):
        return abs(a - c) + abs(b - d)

    def pos_of(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            try:
                return int(x[0]), int(x[1])
            except Exception:
